INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-1', 0, 'Xin chào!', '[{"hanzi":"你好","pinyin":"nǐ hǎo","hanViet":"NHĨ HẢO","meaning":"Xin chào","pos":"Cụm từ","example":{"zh":"李明，你好。","pinyinPerChar":[{"c":"李","py":"lǐ"},{"c":"明","py":"míng"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chào Lý Minh"}},{"hanzi":"王老师","pinyin":"Wáng lǎoshī","hanViet":"VƯƠNG LÃO SƯ","meaning":"Cô Vương","pos":"Danh từ","example":{"zh":"王老师，您好。","pinyinPerChar":[{"c":"王","py":"wáng"},{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"，","py":"，"},{"c":"您","py":"nín"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Xin chào cô Vương"}},{"hanzi":"大家","pinyin":"dàjiā","hanViet":"ĐẠI GIA","meaning":"Mọi người","pos":"Đại từ","example":{"zh":"大家好，我是新学生。","pinyinPerChar":[{"c":"大","py":"dà"},{"c":"家","py":"jiā"},{"c":"好","py":"hǎo"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"新","py":"xīn"},{"c":"学","py":"xué"},{"c":"生","py":"sheng"},{"c":"。","py":"。"}],"vi":"Chào mọi người, tôi là học sinh mới"}},{"hanzi":"好","pinyin":"hǎo","hanViet":"HẢO","meaning":"Tốt, khỏe","pos":"Tính từ","example":{"zh":"老师，您好。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"，","py":"，"},{"c":"您","py":"nín"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Xin chào thầy"}},{"hanzi":"学生","pinyin":"xuésheng","hanViet":"HỌC SINH","meaning":"Học sinh","pos":"Danh từ","example":{"zh":"我是这里的学生。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"是","py":"shì"},{"c":"这","py":"zhè"},{"c":"里","py":"lǐ"},{"c":"的","py":"de"},{"c":"学","py":"xué"},{"c":"生","py":"sheng"},{"c":"。","py":"。"}],"vi":"Tôi là học sinh ở đây"}},{"hanzi":"们","pinyin":"men","hanViet":"MÔN","meaning":"Các, những (hậu tố chỉ số nhiều)","pos":"Hậu tố","example":{"zh":"老师们好。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"们","py":"men"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chào các thầy cô"}},{"hanzi":"老师","pinyin":"lǎos