INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-3', 2, 'Số đếm', '[{"hanzi":"一","pinyin":"yī","hanViet":"NHẤT","meaning":"Một","pos":"Số từ","example":{"zh":"我要一杯茶。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"一","py":"yī"},{"c":"杯","py":"bēi"},{"c":"茶","py":"chá"},{"c":"。","py":"。"}],"vi":"Tôi muốn một cốc trà"}},{"hanzi":"二","pinyin":"èr","hanViet":"NHỊ","meaning":"Hai","pos":"Số từ","example":{"zh":"一加一是二。","pinyinPerChar":[{"c":"一","py":"yī"},{"c":"加","py":"jiā"},{"c":"一","py":"yī"},{"c":"是","py":"shì"},{"c":"二","py":"èr"},{"c":"。","py":"。"}],"vi":"Một cộng một bằng hai"}},{"hanzi":"三","pinyin":"sān","hanViet":"TAM","meaning":"Ba","pos":"Số từ","example":{"zh":"我有三本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"三","py":"sān"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi có ba quyển sách"}},{"hanzi":"四","pinyin":"sì","hanViet":"TỨ","meaning":"Bốn","pos":"Số từ","example":{"zh":"现在四点。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"四","py":"sì"},{"c":"点","py":"diǎn"},{"c":"。","py":"。"}],"vi":"Bây giờ là bốn giờ"}},{"hanzi":"五","pinyin":"wǔ","hanViet":"NGŨ","meaning":"Năm","pos":"Số từ","example":{"zh":"今天星期五。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"星","py":"xīng"},{"c":"期","py":"qī"},{"c":"五","py":"wǔ"},{"c":"。","py":"。"}],"vi":"Hôm nay là thứ Sáu"}},{"hanzi":"六","pinyin":"liù","hanViet":"LỤC","meaning":"Sáu","pos":"Số từ","example":{"zh":"现在六点。","pinyinPerChar":[{"c":"现","py":"xiàn"},{"c":"在","py":"zài"},{"c":"六","py":"liù"},{"c":"点","py":"diǎn"},{"c":"。","py":"。"}],"vi":"Bây giờ là sáu giờ"}},{"hanzi":"七","pinyin":"qī","hanViet":"THẤT","meaning":"Bảy","pos":"Số từ","example":{"zh":"七月七号。","pinyinPerChar":[{"c":"七","py":"qī"},{"c":"月","py":"yuè"},{"c":"七","py":"qī"},{"c":"号","py":"hào"},{"c":"。","py":"。"}],"vi":"Tháng Bảy ngày bảy"}},{"hanzi":"八","pinyin":"bā","hanViet":"BÁT","meaning":"Tám","pos":"Số t