INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-12', 11, 'Tính từ hay dùng', '[{"hanzi":"大","pinyin":"dà","hanViet":"ĐẠI","meaning":"Lớn","pos":"Tính từ","example":{"zh":"这个学校很大。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Trường này rất lớn"}},{"hanzi":"小","pinyin":"xiǎo","hanViet":"TIỂU","meaning":"Nhỏ","pos":"Tính từ","example":{"zh":"我的猫很小。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"猫","py":"māo"},{"c":"很","py":"hěn"},{"c":"小","py":"xiǎo"},{"c":"。","py":"。"}],"vi":"Con mèo của tôi rất nhỏ"}},{"hanzi":"多","pinyin":"duō","hanViet":"ĐA","meaning":"Nhiều","pos":"Tính từ","example":{"zh":"水果很多。","pinyinPerChar":[{"c":"水","py":"shuǐ"},{"c":"果","py":"guǒ"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"。","py":"。"}],"vi":"Trái cây thì nhiều"}},{"hanzi":"少","pinyin":"shǎo","hanViet":"THIỂU","meaning":"Ít","pos":"Tính từ","example":{"zh":"今天人很少。","pinyinPerChar":[{"c":"今","py":"jīn"},{"c":"天","py":"tiān"},{"c":"人","py":"rén"},{"c":"很","py":"hěn"},{"c":"少","py":"shǎo"},{"c":"。","py":"。"}],"vi":"Hôm nay người rất ít"}},{"hanzi":"高兴","pinyin":"gāo xìng","hanViet":"CAO HƯNG","meaning":"Vui mừng","pos":"Tính từ","example":{"zh":"认识你很高兴。","pinyinPerChar":[{"c":"认","py":"rèn"},{"c":"识","py":"shi"},{"c":"你","py":"nǐ"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xìng"},{"c":"。","py":"。"}],"vi":"Rất vui khi được biết bạn"}},{"hanzi":"漂亮","pinyin":"piào liàng","hanViet":"PHIÊU LIỆU","meaning":"Xinh đẹp","pos":"Tính từ","example":{"zh":"她很漂亮。","pinyinPerChar":[{"c":"她","py":"tā"},{"c":"很","py":"hěn"},{"c":"漂","py":"piào"},{"c":"亮","py":"liàng"},{"c":"。","py":"。"}],"vi":"Cô ấy rất xinh"}},{"hanzi":"贵","pinyin":"guì","hanViet":"QUÝ","meaning":"Đắt","pos":"Tính từ","example":{"zh":"这个太贵了。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"太","py":"tài"},{"c":"贵","py"