INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-13', 12, 'Động từ & tồn tại', '[{"hanzi":"是","pinyin":"shì","hanViet":"THỊ","meaning":"Là, thì là","pos":"Động từ","example":{"zh":"他是我的朋友。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"朋","py":"péng"},{"c":"友","py":"you"},{"c":"。","py":"。"}],"vi":"Anh ấy là bạn của tôi"}},{"hanzi":"有","pinyin":"yǒu","hanViet":"HỮU","meaning":"Có, sở hữu","pos":"Động từ","example":{"zh":"我有很多书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"有","py":"yǒu"},{"c":"很","py":"hěn"},{"c":"多","py":"duō"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi có nhiều sách"}},{"hanzi":"来","pinyin":"lái","hanViet":"LAI","meaning":"Đến","pos":"Động từ","example":{"zh":"他明天来。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Anh ấy đến vào ngày mai"}},{"hanzi":"去","pinyin":"qù","hanViet":"KHỨ","meaning":"Đi","pos":"Động từ","example":{"zh":"我去商店。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"商","py":"shāng"},{"c":"店","py":"diàn"},{"c":"。","py":"。"}],"vi":"Tôi đi cửa hàng"}},{"hanzi":"想","pinyin":"xiǎng","hanViet":"TƯỞNG","meaning":"Muốn","pos":"Động từ","example":{"zh":"我想喝茶。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"想","py":"xiǎng"},{"c":"喝","py":"hē"},{"c":"茶","py":"chá"},{"c":"。","py":"。"}],"vi":"Tôi muốn uống trà"}},{"hanzi":"会","pinyin":"huì","hanViet":"HỘI","meaning":"Biết, có thể","pos":"Động từ","example":{"zh":"我会说汉语。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"会","py":"huì"},{"c":"说","py":"shuō"},{"c":"汉","py":"hàn"},{"c":"语","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Tôi biết nói tiếng Trung"}},{"hanzi":"能","pinyin":"néng","hanViet":"NĂNG","meaning":"Có thể","pos":"Động từ","example":{"zh":"你能来吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"能","py":"néng"},{"c":"来","py":"lái"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn đến được không?"}},{"