INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-14', 13, 'Phụ từ & phủ định', '[{"hanzi":"的","pinyin":"de","hanViet":"ĐÍCH","meaning":"(Trợ từ sở hữu)","pos":"Trợ từ","example":{"zh":"这是我的书。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Đây là sách của tôi"}},{"hanzi":"吗","pinyin":"ma","hanViet":"MA","meaning":"(Trợ từ nghi vấn)","pos":"Trợ từ","example":{"zh":"你是学生吗？","pinyinPerChar":[{"c":"你","py":"nǐ"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"sheng"},{"c":"吗","py":"ma"},{"c":"？","py":"？"}],"vi":"Bạn là học sinh phải không?"}},{"hanzi":"呢","pinyin":"ne","hanViet":"NÍ","meaning":"(Trợ từ hỏi lại)","pos":"Trợ từ","example":{"zh":"我很好，你呢？","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"呢","py":"ne"},{"c":"？","py":"？"}],"vi":"Tôi ổn, còn bạn?"}},{"hanzi":"了","pinyin":"le","hanViet":"LIỄU","meaning":"(Trợ từ hoàn thành)","pos":"Trợ từ","example":{"zh":"下雨了。","pinyinPerChar":[{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"了","py":"le"},{"c":"。","py":"。"}],"vi":"Trời mưa rồi"}},{"hanzi":"不","pinyin":"bú","hanViet":"BẤT","meaning":"Không, chẳng","pos":"Phó từ","example":{"zh":"我不去。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"不","py":"bú"},{"c":"去","py":"qù"},{"c":"。","py":"。"}],"vi":"Tôi không đi"}},{"hanzi":"没","pinyin":"méi","hanViet":"MẠT","meaning":"Chưa, không có","pos":"Phó từ","example":{"zh":"我没有钱。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"没","py":"méi"},{"c":"有","py":"yǒu"},{"c":"钱","py":"qián"},{"c":"。","py":"。"}],"vi":"Tôi không có tiền"}},{"hanzi":"也","pinyin":"yě","hanViet":"DÃ","meaning":"Cũng","pos":"Phó từ","example":{"zh":"他也是学生。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"也","py":"yě"},{"c":"是","py":"shì"},{"c":"学","py":"xué"},{"c":"生","py":"sheng"},{"c":"。","py":"。"}],"vi":"Anh ấy cũng là học sinh"}},{"hanzi":"都"