INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk1', 'lesson-15', 14, 'Từ hay gặp', '[{"hanzi":"爱","pinyin":"ài","hanViet":"ÁI","meaning":"Yêu","pos":"Động từ","example":{"zh":"我爱你。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"爱","py":"ài"},{"c":"你","py":"nǐ"},{"c":"。","py":"。"}],"vi":"Tôi yêu bạn"}},{"hanzi":"请","pinyin":"qǐng","hanViet":"THỈNH","meaning":"Mời, xin","pos":"Động từ","example":{"zh":"请坐。","pinyinPerChar":[{"c":"请","py":"qǐng"},{"c":"坐","py":"zuò"},{"c":"。","py":"。"}],"vi":"Mời ngồi"}},{"hanzi":"喂","pinyin":"wèi","hanViet":"VI","meaning":"A-lô (khi gọi điện)","pos":"Thán từ","example":{"zh":"喂，你好！","pinyinPerChar":[{"c":"喂","py":"wèi"},{"c":"，","py":"，"},{"c":"你","py":"nǐ"},{"c":"好","py":"hǎo"},{"c":"！","py":"！"}],"vi":"A-lô, xin chào!"}},{"hanzi":"在","pinyin":"zài","hanViet":"TẠI","meaning":"Ở, đang ở","pos":"Động từ","example":{"zh":"我在家里。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"在","py":"zài"},{"c":"家","py":"jiā"},{"c":"里","py":"lǐ"},{"c":"。","py":"。"}],"vi":"Tôi ở trong nhà"}},{"hanzi":"住","pinyin":"zhù","hanViet":"TRỤ","meaning":"Cư trú, sống","pos":"Động từ","example":{"zh":"我住在中国。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"住","py":"zhù"},{"c":"在","py":"zài"},{"c":"中","py":"zhōng"},{"c":"国","py":"guó"},{"c":"。","py":"。"}],"vi":"Tôi sống ở Trung Quốc"}},{"hanzi":"岁","pinyin":"suì","hanViet":"TUỲ","meaning":"Tuổi","pos":"Lượng từ","example":{"zh":"我二十岁。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"二","py":"èr"},{"c":"十","py":"shí"},{"c":"岁","py":"suì"},{"c":"。","py":"。"}],"vi":"Tôi hai mươi tuổi"}},{"hanzi":"狗","pinyin":"gǒu","hanViet":"CẨU","meaning":"Con chó","pos":"Danh từ","example":{"zh":"我家的狗很大。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"家","py":"jiā"},{"c":"的","py":"de"},{"c":"狗","py":"gǒu"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Con chó nhà tôi rất to"}},{"hanzi":"猫","pinyin":"māo","hanViet":"MAO","meaning":"Con mèo","pos":"Danh từ","example":{"zh":"猫在椅子上。","pinyinPerChar":