INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk2', 'lesson-1', 0, 'Bắt đầu HSK2', '[{"hanzi":"正在","pinyin":"zhèng zài","hanViet":"CHÍNH TẠI","meaning":"Đang (diễn ra)","pos":"Phó từ","example":{"zh":"他正在学习。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"正","py":"zhèng"},{"c":"在","py":"zài"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"。","py":"。"}],"vi":"Anh ấy đang học"}},{"hanzi":"可能","pinyin":"kě néng","hanViet":"KHẢ NĂNG","meaning":"Có thể, khả năng","pos":"Phó từ","example":{"zh":"明天可能下雨。","pinyinPerChar":[{"c":"明","py":"míng"},{"c":"天","py":"tiān"},{"c":"可","py":"kě"},{"c":"能","py":"néng"},{"c":"下","py":"xià"},{"c":"雨","py":"yǔ"},{"c":"。","py":"。"}],"vi":"Ngày mai có thể mưa"}},{"hanzi":"虽然","pinyin":"suī rán","hanViet":"TUY NHIÊN","meaning":"Tuy rằng","pos":"Liên từ","example":{"zh":"虽然很忙，我很高兴。","pinyinPerChar":[{"c":"虽","py":"suī"},{"c":"然","py":"rán"},{"c":"很","py":"hěn"},{"c":"忙","py":"máng"},{"c":"，","py":"，"},{"c":"我","py":"wǒ"},{"c":"很","py":"hěn"},{"c":"高","py":"gāo"},{"c":"兴","py":"xìng"},{"c":"。","py":"。"}],"vi":"Tuy bận, tôi vẫn rất vui"}},{"hanzi":"但是","pinyin":"dàn shì","hanViet":"ĐẠN THỊ","meaning":"Nhưng","pos":"Liên từ","example":{"zh":"东西贵，但是很好。","pinyinPerChar":[{"c":"东","py":"dōng"},{"c":"西","py":"xi"},{"c":"贵","py":"guì"},{"c":"，","py":"，"},{"c":"但","py":"dàn"},{"c":"是","py":"shì"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Đồ đắt, nhưng rất tốt"}},{"hanzi":"因为","pinyin":"yīn wèi","hanViet":"NHÂN VI","meaning":"Vì, bởi vì","pos":"Liên từ","example":{"zh":"我学习汉语，因为我爱中国。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"汉","py":"hàn"},{"c":"语","py":"yǔ"},{"c":"，","py":"，"},{"c":"因","py":"yīn"},{"c":"为","py":"wèi"},{"c":"我","py":"wǒ"},{"c":"爱","py":"ài"},{"c":"中","py":"zhōng"},{"c":"国","py":"guó"},{"c":"。","py":"。"}],"vi":"Tôi học tiếng Trung, vì tôi yêu Trung Quốc"}},{"hanzi":"觉得","pinyin":"jué de","hanViet":"GIÁC ĐẮC","meaning":"Cảm thấy","pos":"