INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk3', 'lesson-1', 0, 'Nhịp sống hằng ngày', '[{"hanzi":"马上","pinyin":"mǎ shàng","hanViet":"MÃ THƯỢNG","meaning":"Ngay lập tức","pos":"Phó từ","example":{"zh":"我马上来。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"马","py":"mǎ"},{"c":"上","py":"shàng"},{"c":"来","py":"lái"},{"c":"。","py":"。"}],"vi":"Tôi đến ngay"}},{"hanzi":"世界","pinyin":"shì jiè","hanViet":"THẾ GIỚI","meaning":"Thế giới","pos":"Danh từ","example":{"zh":"世界很大。","pinyinPerChar":[{"c":"世","py":"shì"},{"c":"界","py":"jiè"},{"c":"很","py":"hěn"},{"c":"大","py":"dà"},{"c":"。","py":"。"}],"vi":"Thế giới rất rộng lớn"}},{"hanzi":"帮助","pinyin":"bāng zhù","hanViet":"BANG TRỢ","meaning":"Giúp đỡ","pos":"Động từ","example":{"zh":"老师帮助我。","pinyinPerChar":[{"c":"老","py":"lǎo"},{"c":"师","py":"shī"},{"c":"帮","py":"bāng"},{"c":"助","py":"zhù"},{"c":"我","py":"wǒ"},{"c":"。","py":"。"}],"vi":"Thầy giúp đỡ tôi"}},{"hanzi":"故事","pinyin":"gù shi","hanViet":"CỐ SỰ","meaning":"Câu chuyện","pos":"Danh từ","example":{"zh":"这个故事很有意思。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"故","py":"gù"},{"c":"事","py":"shi"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"意","py":"yì"},{"c":"思","py":"si"},{"c":"。","py":"。"}],"vi":"Câu chuyện này rất thú vị"}},{"hanzi":"机场","pinyin":"jī chǎng","hanViet":"CƠ TRƯỜNG","meaning":"Sân bay","pos":"Danh từ","example":{"zh":"我去机场。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"去","py":"qù"},{"c":"机","py":"jī"},{"c":"场","py":"chǎng"},{"c":"。","py":"。"}],"vi":"Tôi đi sân bay"}},{"hanzi":"借","pinyin":"jiè","hanViet":"TÁ","meaning":"Mượn, cho vay","pos":"Động từ","example":{"zh":"我借一本书。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"借","py":"jiè"},{"c":"一","py":"yī"},{"c":"本","py":"běn"},{"c":"书","py":"shū"},{"c":"。","py":"。"}],"vi":"Tôi mượn một quyển sách"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk4', 'lesson-1', 0, 'Hướng tới thành công', '[{"hanzi":"成功","pinyin":"chéng gōng","hanViet":"THÀNH CÔNG","meaning":"Thành công","pos":"Danh từ","example":{"zh":"他获得了成功。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"获","py":"huò"},{"c":"得","py":"dé"},{"c":"了","py":"le"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"。","py":"。"}],"vi":"Anh ấy đạt được thành công"}},{"hanzi":"计划","pinyin":"jì huà","hanViet":"KẾ HOẠCH","meaning":"Kế hoạch","pos":"Danh từ","example":{"zh":"我的计划很好。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"的","py":"de"},{"c":"计","py":"jì"},{"c":"划","py":"huà"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Kế hoạch của tôi rất tốt"}},{"hanzi":"广告","pinyin":"guǎng gào","hanViet":"QUẢNG CÁO","meaning":"Quảng cáo","pos":"Danh từ","example":{"zh":"这个广告很有名。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"广","py":"guǎng"},{"c":"告","py":"gào"},{"c":"很","py":"hěn"},{"c":"有","py":"yǒu"},{"c":"名","py":"míng"},{"c":"。","py":"。"}],"vi":"Quảng cáo này rất nổi tiếng"}},{"hanzi":"提高","pinyin":"tí gāo","hanViet":"ĐỀ CAO","meaning":"Nâng cao","pos":"Động từ","example":{"zh":"我要提高汉语水平。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"要","py":"yào"},{"c":"提","py":"tí"},{"c":"高","py":"gāo"},{"c":"汉","py":"hàn"},{"c":"语","py":"yǔ"},{"c":"水","py":"shuǐ"},{"c":"平","py":"píng"},{"c":"。","py":"。"}],"vi":"Tôi muốn nâng cao trình độ tiếng Trung"}},{"hanzi":"效果","pinyin":"xiào guǒ","hanViet":"HIỆU QUẢ","meaning":"Hiệu quả","pos":"Danh từ","example":{"zh":"效果很好。","pinyinPerChar":[{"c":"效","py":"xiào"},{"c":"果","py":"guǒ"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Hiệu quả rất tốt"}},{"hanzi":"竞争","pinyin":"jìng zhēng","hanViet":"CỘNH TRANH","meaning":"Cạnh tranh","pos":"Động từ","example":{"zh":"竞争很厉害。","pinyinPerChar":[{"c":"竞","py":"jìng"},{"c":"争","py":"zhēng"},{"c":"很","py":"hěn"},{"c":"厉","py":"lì"},{"c":"害","py":"hai"},{"c":"。","py"