INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk5', 'lesson-1', 0, 'Chủ đề xã hội', '[{"hanzi":"主题","pinyin":"zhǔ tí","hanViet":"CHỦ ĐỀ","meaning":"Chủ đề","pos":"Danh từ","example":{"zh":"这篇文章的主题很好。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"篇","py":"piān"},{"c":"文","py":"wén"},{"c":"章","py":"zhāng"},{"c":"的","py":"de"},{"c":"主","py":"zhǔ"},{"c":"题","py":"tí"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Chủ đề bài viết này rất hay"}},{"hanzi":"现象","pinyin":"xiàn xiàng","hanViet":"HIỆN TƯỢNG","meaning":"Hiện tượng","pos":"Danh từ","example":{"zh":"这是一种现象。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"是","py":"shì"},{"c":"一","py":"yī"},{"c":"种","py":"zhǒng"},{"c":"现","py":"xiàn"},{"c":"象","py":"xiàng"},{"c":"。","py":"。"}],"vi":"Đây là một loại hiện tượng"}},{"hanzi":"规定","pinyin":"guī dìng","hanViet":"QUY ĐỊNH","meaning":"Quy định","pos":"Danh từ","example":{"zh":"学校有新规定。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"校","py":"xiào"},{"c":"有","py":"yǒu"},{"c":"新","py":"xīn"},{"c":"规","py":"guī"},{"c":"定","py":"dìng"},{"c":"。","py":"。"}],"vi":"Trường có quy định mới"}},{"hanzi":"调查","pinyin":"diào chá","hanViet":"ĐIỀU TRA","meaning":"Điều tra, khảo sát","pos":"Động từ","example":{"zh":"我们做了一项调查。","pinyinPerChar":[{"c":"我","py":"wǒ"},{"c":"们","py":"men"},{"c":"做","py":"zuò"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"项","py":"xiàng"},{"c":"调","py":"diào"},{"c":"查","py":"chá"},{"c":"。","py":"。"}],"vi":"Chúng tôi tiến hành một cuộc khảo sát"}},{"hanzi":"体现","pinyin":"tǐ xiàn","hanViet":"THỂ HIỆN","meaning":"Thể hiện","pos":"Động từ","example":{"zh":"这幅画体现了生活。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"幅","py":"fú"},{"c":"画","py":"huà"},{"c":"体","py":"tǐ"},{"c":"现","py":"xiàn"},{"c":"了","py":"le"},{"c":"生","py":"shēng"},{"c":"活","py":"huó"},{"c":"。","py":"。"}],"vi":"Bức tranh này thể hiện cuộc sống"}}]');
INSERT OR REPLACE INTO content_vocabs (book, page_id, ord, title, words) VALUES ('hsk6', 'lesson-1', 0, 'Ngôn ngữ tinh tế', '[{"hanzi":"沉默","pinyin":"chén mò","hanViet":"TRẦM MỘC","meaning":"Trầm mặc","pos":"Tính từ","example":{"zh":"他沉默了很久。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"沉","py":"chén"},{"c":"默","py":"mò"},{"c":"了","py":"le"},{"c":"很","py":"hěn"},{"c":"久","py":"jiǔ"},{"c":"。","py":"。"}],"vi":"Anh ấy trầm mặc rất lâu"}},{"hanzi":"素质","pinyin":"sù zhì","hanViet":"TỐ CHẤT","meaning":"Tố chất, phẩm chất","pos":"Danh từ","example":{"zh":"他的素质很好。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"的","py":"de"},{"c":"素","py":"sù"},{"c":"质","py":"zhì"},{"c":"很","py":"hěn"},{"c":"好","py":"hǎo"},{"c":"。","py":"。"}],"vi":"Phẩm chất của anh ấy rất tốt"}},{"hanzi":"深刻","pinyin":"shēn kè","hanViet":"THÂM KHẮC","meaning":"Sâu sắc","pos":"Tính từ","example":{"zh":"这个印象很深刻。","pinyinPerChar":[{"c":"这","py":"zhè"},{"c":"个","py":"gè"},{"c":"印","py":"yìn"},{"c":"象","py":"xiàng"},{"c":"很","py":"hěn"},{"c":"深","py":"shēn"},{"c":"刻","py":"kè"},{"c":"。","py":"。"}],"vi":"Ấn tượng này rất sâu sắc"}},{"hanzi":"辩论","pinyin":"biàn lùn","hanViet":"BIỆN LUẬN","meaning":"Tranh luận","pos":"Động từ","example":{"zh":"他们辩论了一个小时。","pinyinPerChar":[{"c":"他","py":"tā"},{"c":"们","py":"men"},{"c":"辩","py":"biàn"},{"c":"论","py":"lùn"},{"c":"了","py":"le"},{"c":"一","py":"yī"},{"c":"个","py":"gè"},{"c":"小","py":"xiǎo"},{"c":"时","py":"shí"},{"c":"。","py":"。"}],"vi":"Họ tranh luận một tiếng đồng hồ"}},{"hanzi":"途径","pinyin":"tú jìng","hanViet":"ĐỒ KINH","meaning":"Con đường, biện pháp","pos":"Danh từ","example":{"zh":"学习是成功的途径。","pinyinPerChar":[{"c":"学","py":"xué"},{"c":"习","py":"xí"},{"c":"是","py":"shì"},{"c":"成","py":"chéng"},{"c":"功","py":"gōng"},{"c":"的","py":"de"},{"c":"途","py":"tú"},{"c":"径","py":"jìng"},{"c":"。","py":"。"}],"vi":"Học tập là con đường dẫn đến thành công"}}]');
